@mount('eif.data')
                                    module;
                                    
                                    import u: ^.utils;
                                    import acc: lib.ft4.accounts;
                                    
                                    entity evm_block {
                                    network_id: integer;
                                    evm_block_height: integer;
                                    evm_block_hash: byte_array;
                                    key network_id, evm_block_height, evm_block_hash;
                                    }
                                    
                                    entity evm_event {
                                    index evm_block;
                                    tnx_hash: byte_array;
                                    log_index: integer;
                                    event_signature: byte_array;
                                    contract_address: byte_array;
                                    indexed_values: byte_array;
                                    non_indexed_values: byte_array;
                                    }
                                    
                                    struct event_data {
                                    tnx_hash: byte_array;
                                    log_index: integer;
                                    signature: byte_array;
                                    contract_address: byte_array;
                                    name: text;
                                    indexed_values: list<gtv>;
                                    non_indexed_values: list<gtv>;
                                    }
                                    
                                    entity evm_account_link {
                                    network_id: integer;
                                    state_n: integer;
                                    evm_beneficiary: byte_array;
                                    key network_id, state_n, evm_beneficiary;
                                    }
                                    
                                    object withdraw_stats {
                                    mutable withdraw_count: integer = 0;
                                    }
                                    
                                    struct auth_id {
                                    account_id: byte_array;
                                    auth_descriptor_id: byte_array;
                                    }
                                    
                                    struct state_data {
                                    state_n: integer;
                                    account: list<gtv>;
                                    }
                                    
                                    struct state_address_dto {
                                    state_n: integer;
                                    evm_address: byte_array;
                                    }
                                    
                                    query get_network_accounts(network_id: integer): list<state_address_dto> {
                                    var accounts = evm_account_link @* { .network_id == network_id };
                                    val accounts_dto = list<state_address_dto>();
                                    for (account in accounts) {
                                    accounts_dto.add(state_address_dto(state_n=account.state_n, evm_address=account.evm_beneficiary));
                                    }
                                    return accounts_dto;
                                    }
                                    
                                    function get_or_create_evm_account_link(network_id: integer, beneficiary: byte_array): evm_account_link {
                                    val account = evm_account_link @? { network_id, beneficiary };
                                    if (empty(account)) {
                                    val last_state_n = evm_account_link @? { } ( @sort_desc .state_n ) limit 1;
                                    val next_state_n = if (empty(last_state_n)) 1 else (last_state_n + 1);
                                    
                                    return create evm_account_link (
                                    network_id,
                                    state_n = next_state_n,
                                    beneficiary
                                    );
                                    }
                                    
                                    return account;
                                    }
                                    
                                    function build_account_state(network_id: integer, beneficiary: byte_array, account: acc.account?) {
                                    val state = list<gtv>();
                                    state.add(byte_array.from_hex(u.to_zero_padded_hex(beneficiary)).to_gtv());
                                    val state_map = build_account_state_fn(network_id, beneficiary, account);
                                    for (k in state_map.keys().sorted()) {
                                    state.add_all(state_map[k]);
                                    }
                                    
                                    return state;
                                    }
                                    
                                    @extendable
                                    function build_account_state_fn(
                                    network_id: integer,
                                    beneficiary: byte_array,
                                    account: acc.account?
                                    ): map<integer, list<gtv>>;

@mount('eif.evm')
                                    module;
                                    
                                    import accounts: lib.ft4.accounts;
                                    import auth: lib.ft4.auth;
                                    
                                    entity evm_account {
                                    key accounts.account;
                                    key address: byte_array;
                                    mutable nonce: integer;
                                    }
                                    
                                    query get_login_message() = "Add key:\n{1}\n\nTo account:\n{2}\n\nWith permission:\nTransfer\n\nNonce: {3}";
                                    query get_register_message() = "Create account for EVM wallet:\n{1}\n\nDisposable key:\n{2}";
                                    query get_evm_signature_nonce(acc: byte_array) = require(
                                    evm_account @? { .address == acc } ( .nonce ), "No account found for the provided pubkey"
                                    );
                                    query get_account_by_evm_address(acc: byte_array) = evm_account @? { .address == acc } ( .account );
                                    query get_account_id_by_evm_address(acc: byte_array) = evm_account @? { .address == acc } ( .account.id );
                                    
                                    operation register_account(evm_addr: byte_array, accounts.auth_descriptor, auth.signature) {
                                    require(op_context.get_signers().size() > 0, "Transaction needs to be signed with disposable key");
                                    require(auth_descriptor.auth_type == accounts.auth_type.S, "Only single sig is supported");
                                    
                                    val pubkey = op_context.get_signers()[0];
                                    val account = accounts.create_account_with_auth(auth_descriptor);
                                    val register_msg = _create_register_message(pubkey, evm_addr);
                                    val recovered_address = auth._recover_evm_address(register_msg, signature);
                                    require(recovered_address == evm_addr, "Signature not valid for the provided key");
                                    
                                    create evm_account ( account, evm_addr, 0 );
                                    }
                                    
                                    operation add_auth_descriptor(account_id: byte_array, accounts.auth_descriptor, auth.signature) {
                                    require(op_context.get_signers().size() > 0, "Transaction needs to be signed with disposable key");
                                    val participants = accounts.get_signers(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes());
                                    require(op_context.get_signers().contains_all(participants), "Transaction not signed by auth descriptor key");
                                    require(_extract_single_sig_args(auth_descriptor).flags == set(["T"]), "Only Transfer permission is allowed");
                                    
                                    val account = accounts.account @ { .id == account_id };
                                    val login_msg = _create_login_message(participants[0], account.id);
                                    val recovered_address = auth._recover_evm_address(login_msg, signature);
                                    val evm_account = evm_account @? { .address == recovered_address };
                                    require(evm_account, "Signature not valid for the selected account");
                                    
                                    accounts.add_auth_descriptor_to_account(account, auth_descriptor, true);
                                    evm_account.nonce += 1;
                                    }
                                    
                                    function _extract_single_sig_args(accounts.auth_descriptor): accounts.single_sig_args {
                                    return accounts.single_sig_args.from_bytes(auth_descriptor.args.to_gtv().to_bytes());
                                    }
                                    
                                    function _create_register_message(pubkey, evm_addr: byte_array): text {
                                    return get_register_message()
                                    .replace("{1}", evm_addr.to_hex().lower_case())
                                    .replace("{2}", pubkey.to_hex().lower_case());
                                    }
                                    
                                    function _create_login_message(pubkey, account_id: byte_array): text {
                                    return get_login_message()
                                    .replace("{1}", pubkey.to_hex().lower_case())
                                    .replace("{2}", account_id.to_hex().lower_case())
                                    .replace("{3}", evm_account @ { .account.id == account_id } ( .nonce ).to_text());
                                    }

@mount('eif.ft4')
                                    module;
                                    
                                    import root: ^.main;
                                    import c: ^.common;
                                    import u: ^.utils;
                                    import ^.evm;
                                    
                                    import admin: lib.ft4.admin;
                                    import accounts: lib.ft4.accounts;
                                    import assets: lib.ft4.assets;
                                    import auth: lib.ft4.auth;
                                    
                                    entity evm_erc20 {
                                    network_id: integer;
                                    address: byte_array;
                                    name: text;
                                    symbol: text;
                                    decimals: integer;
                                    key network_id, address;
                                    }
                                    
                                    entity evm_erc20_withdraw {
                                    key serial: integer;
                                    network_id: integer;
                                    index token: evm_erc20;
                                    index beneficiary: byte_array;
                                    amount: big_integer;
                                    }
                                    
                                    entity evm_erc20_balance {
                                    network_id: integer;
                                    token: evm_erc20;
                                    beneficiary: byte_array;
                                    mutable amount: big_integer;
                                    key token, beneficiary;
                                    }
                                    
                                    entity token_mapping {
                                    key token: evm_erc20;
                                    key asset: assets.asset;
                                    }
                                    
                                    operation add_new_evm_erc20(network_id: integer, token_address: byte_array, name: text, symbol: text, decimals: integer) {
                                    admin.require_admin();
                                    require(empty(evm_erc20 @? { network_id, .address == token_address }), "token already existed");
                                    create evm_erc20(
                                    network_id,
                                    address = token_address,
                                    name,
                                    symbol,
                                    decimals
                                    );
                                    }
                                    
                                    operation add_new_token_mapping(network_id: integer, token_address: byte_array, asset_id: byte_array) {
                                    admin.require_admin();
                                    
                                    val token = require(
                                    evm_erc20 @? { network_id, .address == token_address },
                                    "Token does not exist: " + token_address
                                    );
                                    
                                    val asset = require(
                                    assets.asset @? { .id == asset_id },
                                    "Asset does not exist: " + asset_id
                                    );
                                    
                                    require(
                                    empty(token_mapping @? { token, asset }),
                                    "Token was already mapped: " + token_address
                                    );
                                    
                                    create token_mapping(token, asset);
                                    }
                                    
                                    query get_erc20_withdrawal(network_id: integer, token_address: byte_array, beneficiary: byte_array) {
                                    val token = evm_erc20 @? { network_id, .address == token_address };
                                    if (empty(token)) {
                                    return null;
                                    }
                                    
                                    return evm_erc20_withdraw @* { network_id, token , beneficiary } (@sort_desc .serial, .network_id, token = .token.address, .beneficiary, .amount);
                                    }
                                    
                                    query evm_balance_of_erc20(network_id: integer, token_address: byte_array, beneficiary: byte_array): big_integer {
                                    val t = evm_erc20 @? { network_id, .address == token_address };
                                    if (empty(t)) {
                                    return 0;
                                    }
                                    val b = evm_erc20_balance @? { network_id, .token == t, beneficiary } (.amount);
                                    if (empty(b)) {
                                    return 0;
                                    }
                                    return b;
                                    }
                                    
                                    @extend(c.build_account_state_fn)
                                    function(
                                    network_id: integer,
                                    beneficiary: byte_array,
                                    account: accounts.account?
                                    ): map<integer, list<gtv>> {
                                    val state = list<gtv>();
                                    // 0: ERC20
                                    val erc20_balances = evm_erc20_balance @* { network_id, beneficiary };
                                    val balances = list<assets.balance>();
                                    if (account != null) {
                                    val ft_balances = assets.balance @* { .account == account };
                                    for (ft_balance in ft_balances) {
                                    val token_mapping = token_mapping @? { .asset == ft_balance.asset };
                                    if (token_mapping != null) {
                                    if (token_mapping.token.network_id != network_id) {
                                    continue;
                                    }
                                    balances.add(ft_balance);
                                    }
                                    }
                                    }
                                    val erc20_byte_offset = (erc20_balances.size() + balances.size()) * 2 * 32; // 2 values per entry
                                    state.add(erc20_byte_offset.to_gtv());
                                    
                                    // update state for eif balance
                                    for (balance in erc20_balances) {
                                    state.add(byte_array.from_hex(u.to_zero_padded_hex(balance.token.address)).to_gtv());
                                    state.add((balance.amount).to_gtv());
                                    }
                                    
                                    // update state for ft balance
                                    for (balance in balances) {
                                    val token_mapping = token_mapping @ { .asset == balance.asset };
                                    state.add(byte_array.from_hex(u.to_zero_padded_hex(token_mapping.token.address)).to_gtv());
                                    state.add((balance.amount).to_gtv());
                                    }
                                    
                                    return [0: state];
                                    }
                                    
                                    @extend(root.evm_block_fn)
                                    function(
                                    c.evm_block,
                                    network_id: integer,
                                    token_address: byte_array,
                                    beneficiary: byte_array,
                                    evm.evm_account?,
                                    event: c.event_data,
                                    indexed_values_bytes: byte_array,
                                    non_indexed_values_bytes: byte_array
                                    ) {
                                    if (event.name != "DepositedERC20") return;
                                    // ignore the unsupported token, move to process next events if any
                                    val token = evm_erc20 @? { network_id, .address == token_address };
                                    if (empty(token)) {
                                    log("ignore the unsupported token, move to process next events if any: " + token_address);
                                    return;
                                    }
                                    val token_mapping = token_mapping @? { .token == token };
                                    if (empty(token_mapping)) {
                                    log("no token_mapping");
                                    return;
                                    }
                                    
                                    val ft_asset = token_mapping.asset;
                                    val amount = big_integer.from_gtv(event.non_indexed_values[1]);
                                    val evm_event = create c.evm_event(
                                    evm_block,
                                    tnx_hash = event.tnx_hash,
                                    log_index = event.log_index,
                                    event_signature = event.signature,
                                    contract_address = event.contract_address,
                                    indexed_values = indexed_values_bytes,
                                    non_indexed_values = non_indexed_values_bytes
                                    );
                                    
                                    // if user account does not exist, record the state into EIF for withdraw back to EVM chains later.
                                    // This feature is to avoid losing fund of user
                                    if (empty(evm_account)) {
                                    val name = text.from_gtv(event.non_indexed_values[2]);
                                    val symbol = text.from_gtv(event.non_indexed_values[3]);
                                    val decimals = integer.from_gtv(event.non_indexed_values[4]);
                                    log("record the state into EIF for withdraw back to EVM chains later for beneficiary: " + beneficiary);
                                    deposit_ERC20(network_id, beneficiary, token_address, amount, name, symbol, decimals);
                                    
                                    val account_link = c.get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = c.build_account_state(network_id, beneficiary, null);
                                    val state_data = c.state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    } else {
                                    // mint postchain token for ft account
                                    val ft_account = evm_account.account;
                                    log("mint postchain token for ft account: " + ft_account.id);
                                    assets.Unsafe.mint(ft_account, ft_asset, amount);
                                    val ft_beneficiary = evm.evm_account @ { .account == ft_account } ( .address );
                                    val account_link = c.get_or_create_evm_account_link(token_mapping.token.network_id, ft_beneficiary);
                                    val state = c.build_account_state(network_id, ft_beneficiary, ft_account);
                                    val state_data = c.state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    }
                                    }
                                    
                                    operation deposit_ft_token(c.auth_id, network_id: integer, token_address: byte_array, beneficiary: byte_array, amount: big_integer) {
                                    require(amount > 0, "amount should larger than 0");
                                    val token = require(evm_erc20 @? { network_id, .address == token_address }, "token is not support");
                                    val token_mapping = require(token_mapping @? { token }, "token is not support");
                                    val asset = require(assets.asset @? { .id == token_mapping.asset.id }, "asset does not exist");
                                    
                                    val account = accounts.account @ { .id == auth_id.account_id };
                                    val account_auth_descriptor = accounts.auth_descriptor_by_id(account, auth_id.auth_descriptor_id);
                                    auth._ft_auth(["T"], account, account_auth_descriptor);
                                    
                                    // burn ft token of the account
                                    assets.Unsafe.burn(account, asset, amount);
                                    
                                    // update the postchain EIF state for equivalent account
                                    deposit_ERC20(network_id, beneficiary, token_address, amount, token_mapping.token.name, token_mapping.token.symbol, token_mapping.token.decimals);
                                    
                                    // update relevant account state
                                    update_account_state(account.id, asset.id);
                                    }
                                    
                                    operation bridge_ft_token_to_evm(c.auth_id, network_id: integer, token_address: byte_array, beneficiary: byte_array, amount: big_integer) {
                                    require(amount > 0, "amount should larger than 0");
                                    val token = require(evm_erc20 @? { network_id, .address == token_address }, "token is not supported");
                                    val token_mapping = require(token_mapping @? { token }, "token is not support");
                                    val asset = require(assets.asset @? { .id == token_mapping.asset.id }, "asset does not exist");
                                    
                                    val account = accounts.account @ { .id == auth_id.account_id };
                                    val account_auth_descriptor = accounts.auth_descriptor_by_id(account, auth_id.auth_descriptor_id);
                                    auth._ft_auth(["T"], account, account_auth_descriptor);
                                    
                                    // burn ft token of the account and update relevant account state
                                    assets.Unsafe.burn(account, asset, amount);
                                    update_account_state(account.id, asset.id);
                                    
                                    update c.withdraw_stats(withdraw_count += 1);
                                    val next_serial = c.withdraw_stats.withdraw_count;
                                    
                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );
                                    
                                    val withdraw_info = [
                                    next_serial.to_gtv(),
                                    network_id.to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(token_address)).to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(beneficiary)).to_gtv(),
                                    amount.to_gtv()
                                    ];
                                    
                                    op_context.emit_event("eif_event", withdraw_info.to_gtv());
                                    }
                                    
                                    // user can claim ft asset back to specific account id on postchain after deposit it into EIF
                                    operation claim_ERC20(network_id: integer, token_address: byte_array, beneficiary: byte_array, amount: big_integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text, account_id: byte_array) {
                                    require(amount > 0, "Must withdraw an amount larger than 0");
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, auth._evm_message_hash(pk));
                                    val eth_address = crypto.eth_pubkey_to_address(recovered_pubkey);
                                    require(eth_address == beneficiary, "beneficiary is not correct, " + "b: " + beneficiary + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "participant is not correct, " + participants[0].to_hex() + ", " + pk);
                                    
                                    val token = require(
                                    evm_erc20 @? { network_id, .address == token_address },
                                    "unsupport token: " + token_address
                                    );
                                    val token_mapping = require(
                                    token_mapping @? { .token == token },
                                    "no token mapping"
                                    );
                                    val ft_asset = token_mapping.asset;
                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    require(balance.amount >= amount, "Balance is too low");
                                    update balance(.amount -= amount);
                                    
                                    update c.withdraw_stats(withdraw_count += 1);
                                    val next_serial = c.withdraw_stats.withdraw_count;
                                    
                                    // net_id = 0 means withdraw from postchain snapshot state into ft account
                                    val net_id = 0;
                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id = net_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );
                                    
                                    val withdraw_info = [
                                    next_serial.to_gtv(),
                                    net_id.to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(token_address)).to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(beneficiary)).to_gtv(),
                                    amount.to_gtv()
                                    ];
                                    
                                    val account = accounts.account @ { account_id };
                                    assets.Unsafe.mint(account, ft_asset, amount);
                                    emit_withdraw(network_id, beneficiary, account, withdraw_info);
                                    }
                                    
                                    operation withdraw_ERC20(network_id: integer, token_address: byte_array, beneficiary: byte_array, amount: big_integer,
                                    r: byte_array, s: byte_array, v: integer, pk: text) {
                                    require(amount > 0, "Must withdraw an amount larger than 0");
                                    
                                    // ensure that the signer also control the beneficiary account
                                    val recovered_pubkey = crypto.eth_ecrecover(r, s, v, auth._evm_message_hash(pk));
                                    val eth_address = crypto.eth_pubkey_to_address(recovered_pubkey);
                                    require(eth_address == beneficiary, "beneficiary is not correct, " + "b: " + beneficiary + " e: " + eth_address);
                                    val participants = op_context.get_signers();
                                    require_not_empty(participants, "participants is empty");
                                    require(participants.size() == 1, "only support single auth");
                                    require(participants[0].to_hex() == pk, "participant is not correct, " + participants[0].to_hex() + ", " + pk);
                                    
                                    val token = evm_erc20 @? { network_id, .address == token_address };
                                    if (empty(token)) {
                                    return;
                                    }
                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    require_not_empty(balance, "No balance for this token");
                                    require(balance.amount >= amount, "Balance is too low");
                                    update balance(.amount -= amount);
                                    
                                    update c.withdraw_stats(withdraw_count += 1);
                                    val next_serial = c.withdraw_stats.withdraw_count;
                                    
                                    create evm_erc20_withdraw(
                                    serial = next_serial,
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );
                                    
                                    val withdraw_info = [
                                    next_serial.to_gtv(),
                                    network_id.to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(token_address)).to_gtv(),
                                    byte_array.from_hex(u.to_zero_padded_hex(beneficiary)).to_gtv(),
                                    amount.to_gtv()
                                    ];
                                    
                                    val account = evm.get_account_by_evm_address(eth_address);
                                    emit_withdraw(network_id, beneficiary, account, withdraw_info);
                                    }
                                    
                                    function deposit_ERC20(network_id: integer, beneficiary: byte_array, token_address: byte_array, amount: big_integer, name: text, symbol: text, decimals: integer) {
                                    log("deposit_ERC20: " + token_address + " : " + beneficiary + " : " + name);
                                    var token = evm_erc20 @? { network_id, .address == token_address };
                                    if (empty(token)) {
                                    token = create evm_erc20(
                                    network_id,
                                    address = token_address,
                                    name,
                                    symbol,
                                    decimals
                                    );
                                    }
                                    
                                    val balance = evm_erc20_balance @? { network_id, token, beneficiary };
                                    if (empty(balance)) {
                                    create evm_erc20_balance(
                                    network_id,
                                    token,
                                    beneficiary,
                                    amount
                                    );
                                    } else {
                                    update balance (.amount += amount);
                                    }
                                    }
                                    
                                    function emit_withdraw(network_id: integer, beneficiary: byte_array, account: accounts.account?, eth_event_data: list<gtv>) {
                                    val account_link = c.get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = c.build_account_state(network_id, beneficiary, account);
                                    val state_data = c.state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    op_context.emit_event("eif_event", eth_event_data.to_gtv());
                                    }
                                    
                                    @extend(assets.after_transfer) function(from: accounts.account, to: accounts.account, assets.asset, amount: big_integer) {
                                    update_account_state(from.id, asset.id);
                                    update_account_state(to.id, asset.id);
                                    }
                                    
                                    function update_account_state(account_id: byte_array, asset_id: byte_array) {
                                    val account = accounts.account @ { .id == account_id };
                                    val beneficiary = evm.evm_account @ { .account == account } ( .address );
                                    val asset = assets.asset @ { .id == asset_id };
                                    val token_mapping = token_mapping @? { .asset == asset };
                                    if (empty(token_mapping)) {
                                    return;
                                    }
                                    val network_id = token_mapping.token.network_id;
                                    val account_link = c.get_or_create_evm_account_link(network_id, beneficiary);
                                    val state = c.build_account_state(network_id, beneficiary, account);
                                    val state_data = c.state_data(
                                    account_link.state_n,
                                    account = state
                                    );
                                    op_context.emit_event("eif_state", state_data.to_gtv());
                                    }

import c: ^.common;
                                    import ^.evm;
                                    
                                    query get_last_evm_block(network_id: integer) {
                                    return c.evm_block @? { network_id } ( @sort_desc .evm_block_height, .evm_block_hash ) limit 1;
                                    }
                                    
                                    operation __evm_block(
                                    network_id: integer,
                                    evm_block_height: integer,
                                    evm_block_hash: byte_array,
                                    events: list<c.event_data>
                                    ) {
                                    _evm_block(network_id, evm_block_height, evm_block_hash, events);
                                    }
                                    
                                    function _evm_block(
                                    network_id: integer,
                                    evm_block_height: integer,
                                    evm_block_hash: byte_array,
                                    events: list<c.event_data>
                                    ) {
                                    val evm_block = create c.evm_block (
                                    network_id,
                                    evm_block_height,
                                    evm_block_hash
                                    );
                                    
                                    for (event in events) {
                                    var indexed_values_bytes = x"";
                                    for (value in event.indexed_values) {
                                    indexed_values_bytes += value.to_bytes();
                                    }
                                    var non_indexed_values_bytes = x"";
                                    for (value in event.non_indexed_values) {
                                    non_indexed_values_bytes += value.to_bytes();
                                    }
                                    
                                    // ignore invalid events' network id
                                    val net_id = integer.from_gtv(event.non_indexed_values[0]);
                                    if (net_id != network_id) {
                                    log("ignore invalid events' network id: " + net_id + " : " + network_id);
                                    continue;
                                    }
                                    
                                    val beneficiary = byte_array.from_gtv(event.indexed_values[0]);
                                    val token_address = byte_array.from_gtv(event.indexed_values[1]);
                                    val evm_account = evm.evm_account @? { .address == beneficiary };
                                    
                                    evm_block_fn(
                                    evm_block,
                                    network_id,
                                    token_address,
                                    beneficiary,
                                    evm_account,
                                    event,
                                    indexed_values_bytes,
                                    non_indexed_values_bytes
                                    );
                                    }
                                    }
                                    
                                    @extendable
                                    function evm_block_fn(
                                    c.evm_block,
                                    network_id: integer,
                                    token_address: byte_array,
                                    beneficiary: byte_array,
                                    evm.evm_account?,
                                    event: c.event_data,
                                    indexed_values_bytes: byte_array,
                                    non_indexed_values_bytes: byte_array
                                    );

struct single_sig_args {
flags: set<text>;
signer: byte_array;
}

struct multi_sig_args {
flags: set<text>;
signatures_required: integer;
signers: list<byte_array>;
}

/*
* Returns VALID if valid.
*/
function check_single_sig_auth(args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
if(signers.size() > 1) {
return utils.invalid("Single sig Auth Descriptor must have only one signer.");
}
if (signers.size() < 1) {
return utils.invalid("Single sig Auth Descriptor's signer list is empty.");
}

val ss_args = single_sig_args.from_bytes(args);
if ( check_required_flags(ss_args.flags, required_flags)) {
if (op_context.is_signer(signers[0])) {
return utils.VALID;
} else {
return utils.invalid("The auth descriptor signer did not sign the transaction.");
}
} else {
return utils.invalid("Some required flags " + required_flags.to_text() + " are missing on the (single sig) Auth Descriptor.");
}
}

/*
* Returns VALID if valid.
*/
function check_multi_sig_auth(args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
val multi_sign_args = multi_sig_args.from_bytes(args);
if (not (check_required_flags(multi_sign_args.flags, required_flags))) {
return utils.invalid("Some required flags " + required_flags.to_text() + " are missing on the (multi sig) Auth Descriptor.");
}
var num_sign = multi_sign_args.signatures_required;
for(s in signers) {
if(op_context.is_signer(s)) {
num_sign -= 1;
if(num_sign < 1) {
return utils.VALID;
}
}
}
return utils.invalid("Transaction must be signed by at least " + multi_sign_args.signatures_required + " signers in the Auth Descriptor.");
}

/*
* Returns false if any of the required flags are missing from the "flags" set.
*/
function check_required_flags(flags: set<text>, required_flags: list<text>): boolean {
return flags.contains_all(required_flags);
}

/*
* Returns the set of flags found in the "args" parameter.
*/
function get_flags_from_args(a_t: auth_type, args: byte_array): set<text> {
return when (a_t) {
S -> single_sig_args.from_bytes(args).flags;
M -> multi_sig_args.from_bytes(args).flags;
};
}

/*
* Returns VALID if authentication arguments are valid.
*/
function check_auth_args(a_t: auth_type, args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
return when (a_t) {
S -> check_single_sig_auth(args, signers, required_flags);
M -> check_multi_sig_auth(args, signers, required_flags);
};
}

function get_signers(a_t: auth_type, args: byte_array): list<byte_array>{
var signers: list<byte_array>? = null;
if (a_t == auth_type.S){
signers = [single_sig_args.from_bytes(args).signer];
}
if (a_t == auth_type.M) {
signers = multi_sig_args.from_bytes(args).signers;
}
//TODO: add extendable callback for custom types
return require(signers, "Unknown auth_descriptor type"); // or return empty list?
}

enum rule_variable {
                                    block_height,
                                    block_time,
                                    op_count
                                    }

                                    enum rule_operator {
                                    lt,
                                    le,
                                    eq,
                                    ge,
                                    gt
                                    }

                                    struct rule_expression {
                                    operator: rule_operator;
                                    variable: rule_variable;
                                    value: integer;
                                    }

                                    struct rule_parameters {
                                    variable: rule_variable;
                                    value: integer;
                                    }

                                    /*
                                    * Operator functions
                                    */

                                    function greater_than(rule_parameters): rule_expression {
                                    return rule_expression(
                                    rule_parameters.variable,
                                    rule_operator.gt,
                                    rule_parameters.value
                                    );
                                    }

                                    function greater_or_equal(rule_parameters): rule_expression {
                                    return rule_expression(
                                    rule_parameters.variable,
                                    rule_operator.ge,
                                    rule_parameters.value
                                    );
                                    }

                                    function equals(rule_parameters): rule_expression {
                                    return rule_expression(
                                    rule_parameters.variable,
                                    rule_operator.eq,
                                    rule_parameters.value
                                    );
                                    }

                                    function less_than(rule_parameters): rule_expression {
                                    return rule_expression(
                                    rule_parameters.variable,
                                    rule_operator.lt,
                                    rule_parameters.value
                                    );
                                    }

                                    function less_or_equal(rule_parameters): rule_expression {
                                    return rule_expression(
                                    rule_parameters.variable,
                                    rule_operator.le,
                                    rule_parameters.value
                                    );
                                    }

                                    /*
                                    * Rule variable functions
                                    */

                                    function block_height(integer): rule_parameters {
                                    return rule_parameters(
                                    rule_variable.block_height,
                                    integer
                                    );
                                    }

                                    function block_time(integer): rule_parameters {
                                    return rule_parameters(
                                    rule_variable.block_time,
                                    integer
                                    );
                                    }

                                    function op_count(integer): rule_parameters {
                                    return rule_parameters(
                                    rule_variable.op_count,
                                    integer
                                    );
                                    }

val GTV_NULL = null.to_gtv();
                                    val GTV_NULL_BYTES = null.to_gtv().to_bytes();

                                    function serialize_rules(rules: list<rule_expression>): gtv {
                                    if (rules.size() == 0) {
                                    return GTV_NULL;
                                    }
                                    if (rules.size() == 1) {
                                    return rule_expression_to_gtv(rules[0]);
                                    }

                                    val rules_gtv = ["and".to_gtv()];
                                    for (rule in rules) {
                                    rules_gtv.add(rule_expression_to_gtv(rule));
                                    }
                                    return rules_gtv.to_gtv();
                                    }

                                    function rule_expression_to_gtv(rule_expression): gtv = [
                                    rule_expression.operator.name.to_gtv(),
                                    rule_expression.variable.name.to_gtv(),
                                    rule_expression.value.to_gtv()
                                    ].to_gtv();

                                    function rule_expression_from_gtv(gtv) {
                                    val components = list<gtv>.from_gtv(gtv);
                                    val operator_name = text.from_gtv(components[0]);
                                    val variable_name = text.from_gtv(components[1]);
                                    val value = integer.from_gtv(components[2]);

                                    val operator = require(
                                    rule_operator.values() @? { .name == operator_name },
                                    "Unknown rule operator %s".format(operator_name)
                                    );

                                    val variable = require(
                                    rule_variable.values() @? { .name == variable_name },
                                    "Unknown rule variable %s".format(variable_name)
                                    );

                                    return rule_expression(
                                    operator,
                                    variable,
                                    value
                                    );
                                    }

                                    function map_rule_expressions_from_gtv(gtv_rules: list<gtv>) {
                                    val rules = list<rule_expression>();
                                    for (rule in gtv_rules) {
                                    rules.add(rule_expression_from_gtv(rule));
                                    }
                                    return rules;
                                    }

                                    function have_violating_rules(auth_descriptor: account_auth_descriptor) =
                                    are_rules_violating(gtv.from_bytes(auth_descriptor.rules), load_variables(auth_descriptor.ctr));

                                    function load_variables(op_count: integer): map<text, gtv> {
                                    val variables = map<text, gtv>();
                                    variables[rule_variable.op_count.name] = (op_count + 1).to_gtv();
                                    variables[rule_variable.block_height.name] = op_context.block_height.to_gtv();
                                    variables[rule_variable.block_time.name] = op_context.last_block_time.to_gtv();
                                    return variables;
                                    }

                                    function are_rules_violating(rules: gtv, variables: map<text, gtv>): boolean {
                                    if (rules == GTV_NULL) {
                                    return false;
                                    }

                                    val rules_gtv = list<gtv>.from_gtv(rules);

                                    if (rules_gtv[0] != "and".to_gtv()) {
                                    require(
                                    rules_gtv.size() == 3,
                                    "Expected a single rule expression, but got something else"
                                    ); // This error will be caught on the next line as well, but like this we can give a better error message

                                    return is_rule_violated(rule_expression_from_gtv(rules_gtv.to_gtv()), variables);
                                    }

                                    return are_and_rules_violated(map_rule_expressions_from_gtv(rules_gtv.sub(1)), variables);
                                    }

                                    function is_rule_violated(rule: rule_expression, variables: map<text, gtv>): boolean {
                                    return not evaluate_int_variable_rule(rule, variables);
                                    }

                                    function are_and_rules_violated(rules: list<rule_expression>, variables: map<text, gtv>): boolean {
                                    for (rule in rules) {
                                    if (is_rule_violated(rule, variables)) {
                                    return true;
                                    }
                                    }
                                    return false;
                                    }

                                    function is_active(account_auth_descriptor) = are_rules_active(gtv.from_bytes(account_auth_descriptor.rules));

                                    function are_rules_active(rules: gtv): boolean {
                                    if (rules == GTV_NULL) {
                                    return true;
                                    }

                                    val gtv_rules = list<gtv>.from_gtv(rules);
                                    if (gtv_rules[0] == "and".to_gtv()) {
                                    for (rule in gtv_rules.sub(1)) {
                                    if (not is_rule_active(rule_expression_from_gtv(rule))) {
                                    return false;
                                    }
                                    }
                                    return true;
                                    }

                                    return is_rule_active(rule_expression_from_gtv(gtv_rules.to_gtv()));
                                    }

                                    function is_rule_active(rule: rule_expression): boolean {
                                    when (rule.variable) {
                                    rule_variable.block_height -> {
                                    return is_block_height_rule_active(rule);
                                    }
                                    rule_variable.block_time -> {
                                    return is_block_time_rule_active(rule);
                                    }
                                    rule_variable.op_count -> {
                                    return is_op_count_rule_active(rule);
                                    }
                                    }
                                    }

                                    /*
                                    *  Variables
                                    */

                                    function evaluate_int_variable_rule(
                                    rule: rule_expression,
                                    variables: map<text, gtv>
                                    ): boolean {
                                    val current_value = variable_value(
                                    rule.variable,
                                    variables
                                    );
                                    val defined_value = rule.value;

                                    when (rule.operator) {
                                    rule_operator.lt -> {
                                    return current_value < defined_value;
                                    }
                                    rule_operator.le -> {
                                    return current_value <= defined_value;
                                    }
                                    rule_operator.eq -> {
                                    return current_value == defined_value;
                                    }
                                    rule_operator.ge -> {
                                    return current_value >= defined_value;
                                    }
                                    rule_operator.gt -> {
                                    return current_value > defined_value;
                                    }
                                    }
                                    }

                                    function variable_value(
                                    variable: rule_variable,
                                    variables: map<text, gtv>
                                    ): integer {
                                    when (variable) {
                                    rule_variable.block_height -> {
                                    return integer.from_gtv(variables[rule_variable.block_height.name]);
                                    }
                                    rule_variable.block_time -> {
                                    return integer.from_gtv(variables[rule_variable.block_time.name]);
                                    }
                                    rule_variable.op_count -> {
                                    return integer.from_gtv(variables[rule_variable.op_count.name]);
                                    }
                                    }
                                    }

                                    /*
                                    * Analyze the rules before assigning them to an authenticator descriptor
                                    */
                                    function validate_auth_descriptor_rules(rules: gtv) {
                                    if (rules == GTV_NULL) {
                                    return;
                                    }

                                    val rules_gtv = list<gtv>.from_gtv(rules);
                                    if (rules_gtv[0] != "and".to_gtv()) {
                                    validate_rule(rule_expression_from_gtv(rules_gtv.to_gtv()));
                                    } else {
                                    require(rules_gtv.size() <= chain_context.args.auth_descriptor.max_rules, "Too many rules");

                                    for (gtv_rule in rules_gtv.sub(1)) {
                                    validate_rule(rule_expression_from_gtv(gtv_rule));
                                    }
                                    }

                                    require((not are_rules_active(rules)) or (not are_rules_violating(rules, load_variables(op_count = 0))),
                                    "Active and invalid rules detected");
                                    }

                                    function validate_rule(rule: rule_expression) {
                                    when (rule.variable) {
                                    rule_variable.block_height -> {
                                    require(rule.value >= 0, "rule variable block_height must be a non-negative value");
                                    }
                                    rule_variable.block_time -> {
                                    require(rule.value >= 0, "rule variable block_time must be a non-negative value");
                                    }
                                    rule_variable.op_count -> {
                                    when (rule.operator) {
                                    rule_operator.lt -> require(rule.value > 1, "rule variable op_count must be a positive value greater than 1");
                                    rule_operator.le -> require(rule.value > 0, "rule variable op_count must be a positive value");
                                    else -> require(false, "rule variable op_count must be lt or le");
                                    }
                                    }
                                    }
                                    }

                                    function update_auth_descriptor_rule_variables(desc: account_auth_descriptor) {
                                    desc.ctr += 1;
                                    return desc;
                                    }

                                    /*
                                    * auth descriptor cleanup
                                    */

                                    function delete_expired_auth_descriptors(account) {
                                    val auth_descriptors = account_auth_descriptor @* { account };

                                    val deleted_descriptors = set<account_auth_descriptor>();

                                    for (auth_descriptor in auth_descriptors) {
                                    if (is_active(auth_descriptor) and have_violating_rules(auth_descriptor)) {
                                    _delete_auth_descriptor(auth_descriptor);
                                    deleted_descriptors.add(auth_descriptor);
                                    }
                                    }

                                    return deleted_descriptors;
                                    }

                                    /****************************************************************************************
                                    *                                     block_time                                       *
                                    ****************************************************************************************/

                                    function is_block_time_rule_active(r: rule_expression): boolean {
                                    when (r.operator) {
                                    rule_operator.gt -> {
                                    return op_context.last_block_time > r.value;
                                    }
                                    rule_operator.ge,
                                    rule_operator.eq -> {
                                    return op_context.last_block_time >= r.value;
                                    }
                                    else -> {
                                    return true;
                                    }
                                    }
                                    }


                                    /****************************************************************************************
                                    *                                  block_height                                        *
                                    ****************************************************************************************/

                                    function is_block_height_rule_active(r: rule_expression): boolean {
                                    when (r.operator) {
                                    rule_operator.gt -> {
                                    return op_context.block_height > r.value;
                                    }
                                    rule_operator.ge,
                                    rule_operator.eq -> {
                                    return op_context.block_height >= r.value;
                                    }
                                    else -> {
                                    return true;
                                    }
                                    }
                                    }


                                    /****************************************************************************************
                                    *                                     op_count                                         *
                                    ****************************************************************************************/

                                    function op_count_variable_initial_value(): gtv {
                                    return (1).to_gtv();
                                    }

                                    function is_op_count_rule_active(rule: rule_expression): boolean {
                                    return true;
                                    }

struct evm_auth_args {
account;
account_auth_descriptor;
signatures: list<auth.signature>;
}

function AuthDescriptor(id: byte_array) = require(
account_auth_descriptor @? { id },
"Provided auth descriptor id does not exist %s".format(id)
);

function Account(id: byte_array) = require(
account @? { id },
"Account not found: %s".format(id)
);

function delete_auth_descriptor_message(gtv) {
val params = struct<delete_auth_descriptor>.from_gtv(gtv);
return "Please sign the message\nto delete auth descriptor:\n%s\n\nfrom account\n{account_id}".format(params.auth_descriptor_id);
}

function delete_auth_descriptor_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
val params = struct<delete_auth_descriptor>.from_gtv(args);
if (params.auth_descriptor_id in auth_descriptor_ids) return params.auth_descriptor_id;

for (ad in accounts.account_auth_descriptor @* { .account.id == account_id, .id in auth_descriptor_ids }) {
if (accounts.has_flags(ad, ["A"])) return ad.id;
}

return null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
scope = rell.meta(delete_auth_descriptor).mount_name,
flags = [],
message = delete_auth_descriptor_message(*),
resolver = delete_auth_descriptor_resolver(*)
);

operation delete_auth_descriptor(auth_descriptor_id: byte_array) {
val account = auth.authenticate();
accounts._delete_auth_descriptor(
accounts.auth_descriptor_by_id(account, auth_descriptor_id)
);
}

function delete_all_auth_descriptors_exclude_message(gtv) {
val params = struct<delete_all_auth_descriptors_exclude>.from_gtv(gtv);
return "Please sign the message\nto delete all auth descriptors excluding:\n%s\n\n from account:\n{account_id}".format(params.auth_descriptor_id);
}

function delete_all_auth_descriptors_exclude_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
val params = struct<delete_all_auth_descriptors_exclude>.from_gtv(args);
if (not (params.auth_descriptor_id in auth_descriptor_ids)) return null;
val auth_descriptor = accounts.account_auth_descriptor @? {
.account.id == account_id,
.id == params.auth_descriptor_id
};

if (empty(auth_descriptor)) return null;
return if (accounts.has_flags(auth_descriptor, ["A"])) auth_descriptor.id else null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
scope = rell.meta(delete_all_auth_descriptors_exclude).mount_name,
flags = ["A"],
message = delete_all_auth_descriptors_exclude_message(*),
resolver = delete_all_auth_descriptors_exclude_resolver(*)
);

operation delete_all_auth_descriptors_exclude(account_id: byte_array, auth_descriptor_id: byte_array) {
val account = accounts.account_by_id(account_id);
val auth_descriptor = accounts.auth_descriptor_by_id(account, auth_descriptor_id);
auth._ft_auth(["A"], account, auth_descriptor);

accounts._delete_all_auth_descriptors_exclude(auth_descriptor);
}

function add_auth_descriptor_message(gtv) {
val params = struct<add_auth_descriptor>.from_gtv(gtv);
val flags = params.new_desc.args[0];

return "Please sign the message\nto add auth descriptor\nwith flags:\n%s\n\nto account:\n{account_id}".format(flags);
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
scope = rell.meta(add_auth_descriptor).mount_name,
flags = ["A"],
message = add_auth_descriptor_message(*)
);

operation add_auth_descriptor(new_desc: accounts.auth_descriptor) {
val account = auth.authenticate();
accounts.add_auth_descriptor_to_account(account, new_desc);
}

query get_config() {
return (
rate_limit = accounts.get_rate_limit_config()
);
}

query get_account_rate_limit_last_update(account_id: byte_array) {
val account = accounts.Account(account_id);
if (accounts.get_rate_limit_config_for_account(account).active == false) return (points = 0, last_update = 0);

return accounts.rl_state @ { account }
(
.points,
.last_update
);
}

query is_auth_descriptor_valid(account_id: byte_array, auth_descriptor_id: byte_array) {
return not accounts.have_violating_rules(accounts.account_auth_descriptor @ {
.account.id == account_id,
.id == auth_descriptor_id
});
}

query get_account_auth_descriptors(id: byte_array) {
return accounts.get_auth_descriptors(id);
}

query get_account_auth_descriptors_by_signer(account_id: byte_array, signer: byte_array) {
return accounts.get_auth_descriptors_by_signer(account_id, signer);
}

query get_account_auth_descriptor_by_id(account_id: byte_array, id: byte_array) {
return accounts.account_auth_descriptor @ {
.id == id,
.account.id == account_id
} ( accounts.get_auth_descriptor_data($.to_struct()) );
}

query get_account_by_id(id: byte_array) {
return accounts.account @? { id } ( .id );
}

query get_account_by_auth_descriptor(accounts.auth_descriptor) {
return accounts.account @? { .id == auth_descriptor.hash() } ( .id );
}

query get_accounts_by_signer(id: byte_array, page_size: integer?, page_cursor: text?) {
return utils.make_page(
accounts.get_paginated_accounts_by_signer(id, page_size, page_cursor),
page_size
);
}

query get_accounts_by_auth_descriptor_id(id: byte_array, page_size: integer?, page_cursor: text?) {
return utils.make_page(
accounts.get_paginated_accounts_by_ad_id(id, page_size, page_cursor),
page_size
);
}

query get_auth_descriptor_nonce(
account_id: byte_array,
auth_descriptor_id: byte_array
) = accounts.account_auth_descriptor @? {
.account.id == account_id,
.id == auth_descriptor_id
} ( .ctr );

@mount('ft4')
                                    module;

                                    struct rate_limit_config {
                                    active: boolean = true;
                                    max_points: integer = 10;
                                    recovery_time: integer = 5000;
                                    points_at_account_creation: integer = 1;
                                    }

                                    struct auth_descriptor_config {
                                    max_rules: integer = 8;
                                    max_number_per_account: integer = 10;
                                    }

                                    struct module_args {
                                    rate_limit: rate_limit_config = rate_limit_config();
                                    auth_descriptor: auth_descriptor_config = auth_descriptor_config();
                                    }

                                    val AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND = min(
                                    200,
                                    chain_context.args.auth_descriptor.max_number_per_account
                                    );

                                    import ^.auth;
                                    import ^.utils;
                                    import ^.version;
                                    import .external;

                                    enum auth_type {
                                    S, M,
                                    }

                                    struct auth_descriptor {
                                    auth_type;
                                    args: list<gtv>;
                                    rules: gtv;
                                    }

                                    entity account {
                                    key id: byte_array;
                                    }

                                    entity account_auth_descriptor {
                                    id: byte_array;
                                    key account, id;
                                    index id;
                                    auth_type;
                                    args: byte_array;
                                    rules: byte_array;
                                    mutable ctr: integer;
                                    created: timestamp;
                                    }

                                    entity auth_descriptor_signer {
                                    key account_auth_descriptor, id: byte_array;
                                    }

                                    // rate limiter
                                    entity rl_state {
                                    key account;
                                    mutable points: integer;
                                    mutable last_update: timestamp;
                                    mutable recovery_time: timestamp;
                                    }


                                    function add_auth_descriptor_to_account(
                                    account,
                                    auth_descriptor,
                                    safe: boolean = true
                                    ): account_auth_descriptor {
                                    require(
                                    (account_auth_descriptor @* { account }).size() <
                                    AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND,
                                    "Max <%d> auth descriptor count reached. Delete some before adding new ones."
                                    .format(AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND)
                                    );

                                    val id = auth_descriptor.hash();

                                    validate_auth_descriptor_args(auth_descriptor);
                                    validate_auth_descriptor_rules(auth_descriptor.rules);

                                    val account_auth_descriptor = create account_auth_descriptor (
                                    account, id,
                                    auth_descriptor.auth_type,
                                    args = auth_descriptor.args.to_gtv().to_bytes(),
                                    rules = auth_descriptor.rules.to_gtv().to_bytes(),
                                    created = latest_time(),
                                    ctr = 0
                                    );

                                    _add_signer(account, auth_descriptor, account_auth_descriptor, safe);
                                    return account_auth_descriptor;
                                    }

                                    function _delete_auth_descriptor(auth_descriptor: account_auth_descriptor) {
                                    require(auth_descriptor.account.id != auth_descriptor.id, "Can't delete initial auth descriptor");
                                    delete auth_descriptor_signer @* { auth_descriptor };
                                    delete auth_descriptor;
                                    }

                                    function _delete_all_auth_descriptors_exclude(auth_descriptor: account_auth_descriptor) {
                                    delete (ads: auth_descriptor_signer, ad: account_auth_descriptor) @* {
                                    ad.account == auth_descriptor.account,
                                    ad.id != auth_descriptor.account.id,
                                    ad.id != auth_descriptor.id,
                                    ads.account_auth_descriptor == ad
                                    };
                                    delete account_auth_descriptor @* {
                                    .account == auth_descriptor.account,
                                    .id != auth_descriptor.account.id,
                                    .id != auth_descriptor.id
                                    };
                                    }

                                    function create_account_with_auth(auth_descriptor): account = _create_account_with_auth(auth_descriptor, safe = true);

                                    function _create_account_with_auth(auth_descriptor, safe: boolean = true): account {
                                    require(auth_descriptor.rules == GTV_NULL, "Cannot create an account with a restricted auth descriptor");

                                    var flags = get_flags(auth_descriptor);
                                    require("A" in flags, "The auth descriptor used to create an account must always have the 'A' flag");

                                    val id = auth_descriptor.hash();
                                    val acc = create account (id);

                                    add_auth_descriptor_to_account(acc, auth_descriptor, safe);

                                    create_rate_limiter_state_for_account(acc);

                                    return acc;
                                    }

                                    function get_flags(auth_descriptor) {
                                    return when (auth_descriptor.auth_type) {
                                    S -> single_sig_args.from_gtv(auth_descriptor.args.to_gtv()).flags;
                                    M -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv()).flags;
                                    };
                                    }

                                    /**
                                    * Checks if an `account_auth_descriptor` has all the specified flags
                                    */
                                    function has_flags(account_auth_descriptor, required_flags: list<text>): boolean {
                                    val flags = get_flags_from_args(account_auth_descriptor.auth_type, account_auth_descriptor.args);
                                    return flags.contains_all(required_flags);
                                    }

                                    function _add_signer(account, auth_descriptor, account_auth_descriptor, safe: boolean = true) {
                                    val signers = get_signers(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes());
                                    require(not safe or op_context.get_signers().size() >= signers.size(), "Too few transaction signers");
                                    for (signer in signers) {
                                    require(not safe or op_context.is_signer(signer), "One signer in the Auth Desc didn't sign this transaction.");
                                    create auth_descriptor_signer(account_auth_descriptor, id = signer);
                                    }
                                    }

                                    function _add_evm_signer(account, auth_descriptor, account_auth_descriptor) {
                                    for (signer in get_signers(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes())) {
                                    create auth_descriptor_signer(account_auth_descriptor, id = signer);
                                    }
                                    }

                                    function auth_descriptor_by_id(account, id: byte_array) = require(
                                    account_auth_descriptor @? { account, id },
                                    "Auth descriptor '%s' not found for account '%s'".format(id, account.id)
                                    );

                                    function account_by_id(id: byte_array) = require(
                                    account @? { id },
                                    "Account not found: '%s'".format(id)
                                    );

                                    function single_sig_auth_descriptor(pubkey, flags: set<text>) = auth_descriptor(
                                    auth_type = auth_type.S,
                                    args = [
                                    flags.to_gtv(),
                                    pubkey.to_gtv()
                                    ],
                                    GTV_NULL
                                    );

                                    function get_auth_descriptors(id: byte_array) {
                                    return account_auth_descriptor @* {
                                    .account.id == id
                                    } (
                                    get_auth_descriptor_data($.to_struct())
                                    );
                                    }

                                    function get_auth_descriptors_by_signer(account_id: byte_array, signer: byte_array) {
                                    return auth_descriptor_signer @* {
                                    .account_auth_descriptor.account.id == account_id,
                                    .id == signer
                                    } (
                                    get_auth_descriptor_data(.account_auth_descriptor.to_struct())
                                    );
                                    }

                                    function get_auth_descriptor_data(ad: struct<account_auth_descriptor>) {
                                    return (
                                    id = ad.id,
                                    account_id = ad.account.id,
                                    auth_type = ad.auth_type,
                                    args = gtv.from_bytes(ad.args),
                                    rules = gtv.from_bytes(ad.rules),
                                    created = ad.created
                                    );
                                    }

                                    function get_paginated_accounts_by_signer(id: byte_array, page_size: integer?, page_cursor: text?) {
                                    val before_rowid = utils.before_rowid(page_cursor);
                                    return auth_descriptor_signer @* {
                                    id,
                                    .rowid > (before_rowid ?: rowid(0))
                                    } (
                                    utils.pagination_result(
                                    data=.account_auth_descriptor.account.to_struct().to_gtv_pretty(),
                                    rowid=.rowid
                                    )
                                    ) limit utils.fetch_data_size(page_size);
                                    }

                                    function get_paginated_accounts_by_ad_id(id: byte_array, page_size: integer?, page_cursor: text?) {
                                    val before_rowid = utils.before_rowid(page_cursor);
                                    return account_auth_descriptor @* {
                                    .id == id,
                                    .rowid > (before_rowid ?: rowid(0))
                                    } (
                                    utils.pagination_result(
                                    data=.account.id.to_gtv_pretty(),
                                    rowid=.rowid
                                    )
                                    ) limit utils.fetch_data_size(page_size);
                                    }

                                    function validate_auth_descriptor_args(auth_descriptor) {
                                    when (auth_descriptor.auth_type) {
                                    S -> single_sig_args.from_gtv(auth_descriptor.args.to_gtv());
                                    M -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv());
                                    }
                                    }

                                    namespace Unsafe {
                                    //WARNING: doesn't check that the account is being created by the owner(s)
                                    function create_account_with_auth(auth_descriptor): account = _create_account_with_auth(auth_descriptor, safe = false);
                                    }

                                    function latest_time() =
                                    if (op_context.exists and op_context.block_height > 0)
                                    op_context.last_block_time
                                    else
                                    block @ {} (@max .timestamp) ?: 0;

                                    function get_max_allowed_auth_descriptor_rules() = chain_context.args.auth_descriptor.max_rules;

/**
                                    * Extend this function to have different rate limiting for different accounts.
                                    *
                                    * @param account  the account
                                    *
                                    * @return rate limit configuration for the account, or `null` to use default config from blockchain configuration.
                                    */
                                    @extendable
                                    function account_rate_limit_config(account): rate_limit_config? = null;

                                    function rate_limit(account) {
                                    val rl_config = get_rate_limit_config_for_account(account);

                                    if (rl_config.active == false) return;

                                    val max_counter = rl_config.max_points;
                                    val recovery_time = rl_config.recovery_time;
                                    val stat = require(
                                    rl_state@?{account} (.points, .last_update),
                                    "Rate limiter state not found for the account with ID: %s".format(account.id)
                                    );
                                    val delta = latest_time() - stat.last_update;
                                    var got_points = 0;
                                    var update_time = stat.last_update;

                                    if (delta > recovery_time) {
                                    got_points = delta / recovery_time;
                                    update_time = stat.last_update + got_points * recovery_time;
                                    if (got_points + stat.points > max_counter) {
                                    got_points = max_counter - stat.points;
                                    // if user is at maximum reset his timer
                                    update_time = latest_time();
                                    }
                                    }

                                    require(stat.points + got_points > 0, "Insufficient rate limiter points");

                                    update rl_state @ { account } (
                                    .points += got_points - 1,
                                    .last_update = update_time
                                    );
                                    }

                                    function current_rate_limit_points(rate_limit_config, rl_state, current_timestamp: timestamp) {
                                    val delta = current_timestamp - rl_state.last_update;
                                    return if (delta > rate_limit_config.recovery_time)
                                    min(rate_limit_config.max_points, rl_state.points + delta / rate_limit_config.recovery_time)
                                    else
                                    rl_state.points;
                                    }

                                    function add_rate_limit_points(account, amount: integer) {
                                    var state = require(
                                    rl_state@?{account},
                                    "Rate limiter state not found for the account with ID: %s".format(account.id)
                                    );
                                    state.points += amount;
                                    }

                                    function get_rate_limit_config(): rate_limit_config = chain_context.args.rate_limit;

                                    function get_rate_limit_config_for_account(account): rate_limit_config =
                                    if (chain_context.args.rate_limit.active == false)
                                    chain_context.args.rate_limit
                                    else
                                    account_rate_limit_config(account) ?: chain_context.args.rate_limit;

                                    function create_rate_limiter_state_for_account(account) {
                                    val rl_config = get_rate_limit_config_for_account(account);

                                    val max_points = rl_config.max_points;
                                    val recovery_time = rl_config.recovery_time;
                                    val points_at_start = rl_config.points_at_account_creation;

                                    create rl_state(account, .points = points_at_start, .last_update = latest_time(), recovery_time);
                                    }

@mount("ft4.admin")
                                    module;

                                    import ^.accounts;
                                    import ^.assets;
                                    import ^.utils;
                                    import ^.version;

                                    struct module_args {
                                    admin_pubkey: pubkey;
                                    }

                                    function require_admin() {
                                    require(
                                    op_context.is_signer(chain_context.args.admin_pubkey),
                                    "Expected admin signature"
                                    );
                                    }

                                    function get_admin_pubkey() {
                                    return chain_context.args.admin_pubkey;
                                    }

operation register_account(accounts.auth_descriptor) {
require_admin();
accounts.Unsafe.create_account_with_auth(auth_descriptor);
}

operation register_asset(name, symbol: text, decimals: integer, icon_url: text) {
require_admin();
assets.Unsafe.register_asset(name, symbol, decimals, chain_context.blockchain_rid, icon_url);
}

operation mint(account_id: byte_array, asset_id: byte_array, amount: big_integer) {
require_admin();
assets.Unsafe.mint(accounts.Account(account_id), assets.Asset(asset_id), amount);
}

operation add_rate_limit_points(account_id: byte_array, amount: integer) {
require_admin();
accounts.add_rate_limit_points(accounts.Account(account_id), amount);
}

entity asset {
key id: byte_array;
name;
key symbol: text;
decimals: integer;
issuing_blockchain_rid: byte_array;
icon_url: text;
mutable total_supply: big_integer;
}

function Asset(id: byte_array) = require(
asset @? { id },
"Asset <%s> not found".format(id)
);

entity balance {
key accounts.account, asset;
mutable amount: big_integer;
}

val max_asset_amount = big_integer.from_hex("ff".repeat(32));

function increase_balance(accounts.account, asset, amount: big_integer): big_integer {
val balance = balance @? { account, asset };
if (balance != null) {
val new_amount = balance.amount + amount;
balance.amount = new_amount;
return new_amount;
} else {
create balance(account, asset, amount);
return amount;
}
}

function deduct_balance(accounts.account, asset, amount: big_integer): big_integer {
val balance = balance @? { account, asset };
require(balance, "User does not have asset <%s> in account <%s>".format(asset.id, account.id));
require(balance.amount >= amount, "Balance is too low");

if (balance.amount - amount == 0L) {
delete balance;
return 0L;
} else {
val new_amount = balance.amount - amount;
balance.amount = new_amount;
return new_amount;
}
}

function get_asset_balance(accounts.account, asset): big_integer {
val balance = balance @? {asset, account};
return if (balance != null) balance.amount else 0L;
}

function map_asset(asset: asset) {
return (
id = asset.id,
name = asset.name,
symbol = asset.symbol,
decimals = asset.decimals,
blockchain_rid = asset.issuing_blockchain_rid,
icon_url = asset.icon_url,
supply = asset.total_supply
);
}

function get_paginated_asset_balances(account_id: byte_array, page_size: integer?, page_cursor: text?): list<utils.pagination_result> {
val before_rowid = utils.before_rowid(page_cursor);
return balance @* {
.account.id == account_id,
.rowid > (before_rowid ?: rowid(0))
} (
utils.pagination_result(
data = (
asset = map_asset(.asset),
amount = .amount
).to_gtv_pretty(),
rowid = .rowid
)
) limit utils.fetch_data_size(page_size);
}

function get_all_assets(page_size: integer?, page_cursor: text?) {
val before_rowid = utils.before_rowid(page_cursor);
return assets.asset @* {
.rowid > (before_rowid ?: rowid(0))
} (
utils.pagination_result(
data = (map_asset($)).to_gtv_pretty(),
rowid = .rowid
)
) limit utils.fetch_data_size(page_size);
}

function get_asset_balances(account_id: byte_array) {
return balance @* { .account.id == account_id } (
asset = map_asset(.asset),
amount = .amount
);
}

function format_amount_with_decimals(amount: big_integer, decimals: integer): text {
require(decimals >= 0, "Decimals must be non-negative. Received: %s".format(decimals));
var amt = amount.to_text();
if (decimals == 0) {
return amt;
} else if (amt.size() > decimals) {
amt = amt.sub(0, amt.size() - decimals) + "." + amt.sub(amt.size() - decimals);
} else {
amt = "0." + "0".repeat(decimals - amt.size()) + amt;
}
return amt;
}

function get_paginated_asset_balances_by_name(name, page_size: integer?, page_cursor: text?) {
val before_rowid = utils.before_rowid(page_cursor);
return assets.asset @* {
.name == name,
.rowid > (before_rowid ?: rowid(0))
} (
utils.pagination_result(
data = (map_asset($)).to_gtv_pretty(),
rowid = .rowid
)
) limit utils.fetch_data_size(page_size);
}

function require_zero_exclusive_asset_amount_limits(value: big_integer, name) {
require(
value <= max_asset_amount,
"%s: value must be lower than 2^256, actual: %d".format(name, value)
);
require(
value > 0L,
"%s: value must be non-zero positive, actual: %d".format(name, value)
);
}

namespace Unsafe {
function mint(accounts.account, asset, amount: big_integer) {
require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
require(
asset.issuing_blockchain_rid == chain_context.blockchain_rid,
"Assets can only be minted on issuing chain"
);
before_mint(account, asset, amount);
increase_balance(account, asset, amount);

asset.total_supply += amount;

require(asset.total_supply <= max_asset_amount, "End total supply must be lower than 2^256");

create transfer_history_entry(
account,
asset,
.delta = amount,
.op_index = op_context.op_index,
.is_input = false
);

after_mint(account, asset, amount);
}

function burn(accounts.account, asset, amount: big_integer) {
require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
require(
asset.issuing_blockchain_rid == chain_context.blockchain_rid,
"Assets can only be burned on issuing chain"
);
require(get_asset_balance(account, asset) >= amount, "Insufficient balance");

before_burn(account, asset, amount);

deduct_balance(account, asset, amount);

asset.total_supply -= amount;

create transfer_history_entry (
account,
asset,
.delta = amount,
.op_index = op_context.op_index,
.is_input = true
);
after_burn(account, asset, amount);
}

function register_asset(
name,
symbol: text,
decimals: integer,
blockchain_rid: byte_array,
icon_url: text): asset {

require(decimals >= 0 and decimals < 79, "Decimals must be between 0 and 78 (included)");

val trimmed_icon_url = icon_url.trim();
require(
(trimmed_icon_url == "") or (trimmed_icon_url.size() <= 2048 and trimmed_icon_url.matches('^\\S+:\\/\\/[^\\s$.?#].[^\\s]*$')),
"Invalid URL for icon"
);

require(blockchain_rid.size() > 0, "blockchain_rid cannot be empty");

val id = (name, blockchain_rid).hash();
return create asset (
id,
name,
symbol,
decimals,
issuing_blockchain_rid=blockchain_rid,
icon_url=trimmed_icon_url,
total_supply=0L
);
}
}

@extendable function before_transfer(from: accounts.account, to: accounts.account, assets.asset, amount: big_integer);

@extendable function after_transfer(from: accounts.account, to: accounts.account, assets.asset, amount: big_integer);

@extendable function before_mint(accounts.account, asset, amount: big_integer);

@extendable function after_mint(accounts.account, asset, amount: big_integer);

@extendable function before_burn(accounts.account, asset, amount: big_integer);

@extendable function after_burn(accounts.account, asset, amount: big_integer);

function transfer_message(gtv) {
val params = struct<transfer>.from_gtv(gtv);
val asset = assets.Asset(params.asset_id);

return "Please sign the message\nto transfer %s %s\n(id: %s)\n\nfrom:\n{account_id}\n\nto:\n%s"
.format(
assets.format_amount_with_decimals(params.amount, asset.decimals),
asset.name,
asset.id,
params.receiver_id
);
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
scope = rell.meta(transfer).mount_name,
flags = ["T"],
message = transfer_message(*)
);

operation transfer(receiver_id: byte_array, asset_id: byte_array, amount: big_integer) {
val sender = auth.authenticate();
val asset = assets.Asset(asset_id);
assets.Unsafe.transfer_to_recipient_id(sender, receiver_id, asset, amount);
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
scope = rell.meta(burn).mount_name,
flags = ["T"],
message = burn_message(*)
);

function burn_message(gtv) {
val params = struct<burn>.from_gtv(gtv);
val asset = assets.Asset(params.asset_id);

return "Please sign the message\nto burn %s %s\n\nfrom:\n{account_id}"
.format(
assets.format_amount_with_decimals(params.amount, asset.decimals),
asset.name
);
}

operation burn(asset_id: byte_array, amount: big_integer) {
val account = auth.authenticate();
assets.Unsafe.burn(account, assets.Asset(asset_id), amount);
}

query get_asset_balances(account_id: byte_array, page_size: integer?, page_cursor: text?) {
return utils.make_page(
assets.get_paginated_asset_balances(account_id, page_size, page_cursor),
page_size
);
}

query get_asset_balance(account_id: byte_array, asset_id: byte_array) {
return assets.balance @? {
.account.id == account_id,
.asset.id == asset_id
} (
asset = assets.map_asset(.asset),
amount = .amount
);
}

query get_assets_by_name(name, page_size: integer?, page_cursor: text?) {
return utils.make_page(
assets.get_paginated_asset_balances_by_name(name, page_size, page_cursor),
page_size
);
}

query get_asset_by_id(asset_id: byte_array) {
return assets.asset @? { .id == asset_id } ( assets.map_asset($) );
}

query get_asset_by_symbol(symbol: text) {
return assets.asset @? { .symbol == symbol } ( assets.map_asset($) );
}

query get_all_assets(page_size: integer?, page_cursor: text?) {
return utils.make_page(
assets.get_all_assets(page_size, page_cursor),
page_size
);
}

query get_transfer_history(account_id: byte_array, filter: assets.filter, page_size: integer?, page_cursor: text?) {
val account = accounts.account @? { account_id };
if (empty(account)) return null;

val paginated_transfers = assets.get_paginated_transfers(
account = account,
asset = null,
filter = filter,
height = null,
page_size = page_size,
page_cursor = page_cursor);
return utils.make_page(paginated_transfers, page_size);
}

query get_transfer_history_from_height(height: integer, asset_id: byte_array?, page_size: integer?, page_cursor: text?) {
val asset = if (asset_id != null) assets.Asset(asset_id) else null;

val paginated_transfers = assets.get_paginated_transfers(
account = null,
asset = asset,
filter = assets.filter(null),
height = height,
page_size = page_size,
page_cursor = page_cursor);
return utils.make_page(paginated_transfers, page_size);
}

query get_transfer_history_entry(rowid) {
val entry = assets.transfer_history_entry @? { .rowid == rowid };
return if (empty(entry)) null else assets.extract_data_from_transfer_history_entry(entry);
}

query get_transfer_details(tx_rid: byte_array, op_index: integer) =
assets.get_transfer_details(tx_rid, op_index);

query get_transfer_details_by_asset(tx_rid: byte_array, op_index: integer, asset_id: byte_array) =
assets.get_transfer_details_by_asset(tx_rid, op_index, asset_id);

@log entity transfer_history_entry {
op_index: integer = op_context.op_index; // helps to locate exact position of transfer entry in transaction
index transaction, op_index;

index accounts.account;
index asset;
delta: big_integer;
is_input: boolean;
}

enum transfer_type {
sent,
received,
}

struct filter {
transfer_type?;
}

function extract_data_from_transfer_history_list(
entries: list<transfer_history_entry>
): list<(data:gtv,rowid:rowid)> {
return entries @* {} (
data = extract_data_from_transfer_history_entry($).to_gtv_pretty(),
rowid = .rowid
);
}

function extract_operation_name(entry: transfer_history_entry): text {
val gtx = gtx_transaction.from_gtv(gtv.from_bytes(entry.transaction.tx_data));
return gtx.body.operations[entry.op_index].name;
}

function extract_data_from_transfer_history_entry(entry: transfer_history_entry) {
return (
id = entry.rowid,
delta = entry.delta,
decimals = entry.asset.decimals,
asset = map_asset(entry.asset),
is_input = entry.is_input,
timestamp = entry.transaction.block.timestamp,
block_height = entry.transaction.block.block_height,
tx_rid = entry.transaction.tx_rid,
tx_data = entry.transaction.tx_data,
operation_name = extract_operation_name(entry),
op_index = entry.op_index
);
}

function get_paginated_transfers(accounts.account?, asset?, filter, height: integer?, page_size: integer?, page_cursor: text?) {
var before_rowid: rowid? = null;
if (page_cursor??) {
val cursor = utils.decode_cursor(page_cursor);
before_rowid = cursor.before_rowid;
}

val entries = transfer_history_entry @* {
if (account == null) true else .account == account,
if (asset == null) true else .asset == asset,
if (filter.transfer_type == null) true else .is_input == (filter.transfer_type!! == transfer_type.sent),
if (height == null) true else (.transaction.block.block_height > height),
if (before_rowid??) (.rowid < before_rowid) else true
} (@sort_desc $) limit utils.fetch_data_size(page_size);

return extract_data_from_transfer_history_list(entries) @* {} (
utils.pagination_result(
data = .data,
rowid = .rowid
)
);
}

struct transfer_detail {
account_id: byte_array;
asset_id: byte_array;
delta: big_integer;
is_input: boolean;
}

function get_transfer_details(tx_rid: byte_array, op_index: integer) =
assets.transfer_history_entry @*
{ .transaction.tx_rid == tx_rid, op_index }
(extract_details_from_transfer_history_entry($));

function get_transfer_details_by_asset(tx_rid: byte_array, op_index: integer, asset_id: byte_array) =
assets.transfer_history_entry @*
{ .transaction.tx_rid == tx_rid, op_index, .asset.id == asset_id }
(extract_details_from_transfer_history_entry($));

function extract_details_from_transfer_history_entry(assets.transfer_history_entry) =
transfer_detail(
account_id = transfer_history_entry.account.id,
asset_id = transfer_history_entry.asset.id,
delta = transfer_history_entry.delta,
is_input = transfer_history_entry.is_input
);

@mount('ft4')
                                    module;

                                    import .external;
                                    import ^.accounts;
                                    import ^.assets;
                                    import ^.utils;
                                    import ^.version;

@extendable
                                    function is_create_on_internal_transfer_enabled(): boolean = false;

                                    @extendable
                                    function create_on_internal_transfer(
                                    sender: accounts.account,
                                    recipient_id: byte_array,
                                    asset,
                                    amount: big_integer
                                    );

                                    namespace Unsafe {

                                    function transfer_to_recipient_id(sender: accounts.account, recipient_id: byte_array, assets.asset, amount: big_integer) {
                                    val recipient = accounts.account @? { .id == recipient_id };
                                    if (recipient != null) {
                                    transfer(sender, recipient, asset, amount);
                                    } else {
                                    require(is_create_on_internal_transfer_enabled(),
                                    "Account <%s> does not exist and creating accounts on transfer is not enabled".format(recipient_id));
                                    create_on_internal_transfer(sender, recipient_id, asset, amount);
                                    }
                                    }

                                    function transfer(from: accounts.account, to: accounts.account, assets.asset, amount: big_integer) {
                                    require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
                                    require(from != to, "Sender and receiver have to be different");

                                    before_transfer(from, to, asset, amount);

                                    deduct_balance(from, asset, amount);
                                    create transfer_history_entry(
                                    .account = from,
                                    .asset = asset,
                                    .delta = amount,
                                    .op_index = op_context.op_index,
                                    .is_input = true
                                    );

                                    increase_balance(to, asset, amount);
                                    create transfer_history_entry(
                                    .account = to,
                                    .asset = asset,
                                    .delta = amount,
                                    .op_index = op_context.op_index,
                                    .is_input = false
                                    );

                                    after_transfer(from, to, asset, amount);
                                    }
                                    }

/**
                                    * This function can be extended by users to add custom logic before authentication.
                                    */
                                    @extendable
                                    function before_authenticate(accounts.account, accounts.account_auth_descriptor);

                                    /**
                                    * This function can be extended by users to add custom logic after authentication.
                                    */
                                    @extendable
                                    function after_authenticate(accounts.account, accounts.account_auth_descriptor?);

                                    val EVM_AUTH_OP = "ft4.evm_auth";
                                    val FT_AUTH_OP = "ft4.ft_auth";

                                    function authenticate(is_strict: boolean = true) {
                                    val op = op_context.get_all_operations()[op_context.op_index];
                                    require(op_context.op_index > 0, "Expected at least two operations, make sure that you included auth operation.");

                                    val previous_op = op_context.get_all_operations()[op_context.op_index - 1];
                                    require(
                                    is_auth_op(previous_op),
                                    "Error authenticating operation. Incorrect auth operation %s".format(previous_op.name)
                                    );

                                    val (account, auth_descriptor) = fetch_account_and_auth_descriptor(previous_op.args);
                                    require(
                                    get_first_allowed_auth_descriptor(op.name, op.args.to_gtv(), account.id, [auth_descriptor.id], is_strict),
                                    "The provided auth descriptor is not valid for this operation"
                                    );
                                    before_authenticate(account, auth_descriptor);

                                    accounts.rate_limit(account);

                                    require(not accounts.have_violating_rules(auth_descriptor), "The rules for this auth descriptor have been violated");

                                    val flags = get_auth_flags(op.name, is_strict);

                                    when (previous_op.name) {
                                    EVM_AUTH_OP -> _validate_evm_signature(op, previous_op, is_strict, flags, account, auth_descriptor);
                                    FT_AUTH_OP -> _validate_ft4_signature(flags, account, auth_descriptor);
                                    else -> require(false, "Invalid auth operation: %s".format(previous_op.name));
                                    };

                                    val auth_desc_after = accounts.update_auth_descriptor_rule_variables(auth_descriptor);
                                    val deleted_descriptors = accounts.delete_expired_auth_descriptors(account);

                                    after_authenticate(account, if (auth_desc_after in deleted_descriptors) null else auth_desc_after);

                                    return account;
                                    }

                                    function get_first_allowed_auth_descriptor_by_signers(op_name: name, args: gtv, account_id: byte_array, signers: list<byte_array>, is_strict: boolean) {
                                    val ads = accounts.auth_descriptor_signer @* {
                                    .account_auth_descriptor.account.id == account_id,
                                    .id in signers
                                    } (.account_auth_descriptor);

                                    val flags = get_auth_flags(op_name, is_strict);

                                    val valid_ad_ids = ads @* { accounts.has_flags($, flags) } (.id);

                                    return get_first_allowed_auth_descriptor(op_name, args, account_id, valid_ad_ids, is_strict);
                                    }

                                    function get_first_allowed_auth_descriptor(op_name: name, args: gtv, account_id: byte_array, ad_ids: list<byte_array>, is_strict: boolean) {
                                    if (ad_ids.size() == 0) return null;

                                    val resolver = get_auth_handler(op_name, is_strict=false).resolver;
                                    if (resolver == null) return ad_ids[0];

                                    return resolver(args, account_id, ad_ids);
                                    }

                                    function _ft_auth(required_flags: list<text>, account: accounts.account, auth_descriptor: accounts.account_auth_descriptor) {
                                    accounts.rate_limit(account);

                                    require(not accounts.have_violating_rules(auth_descriptor), "The rules for this auth descriptor have been violated");

                                    _validate_ft4_signature(required_flags, account, auth_descriptor);

                                    accounts.update_auth_descriptor_rule_variables(auth_descriptor);
                                    accounts.delete_expired_auth_descriptors(account);
                                    }

                                    function fetch_account_and_auth_descriptor(auth_args: list<gtv>): (accounts.account, accounts.account_auth_descriptor) {
                                    val account_id = byte_array.from_gtv(auth_args[0]);
                                    val auth_descriptor_id = byte_array.from_gtv(auth_args[1]);

                                    val account = accounts.Account(account_id);
                                    val auth_descriptor = require(
                                    accounts.account_auth_descriptor @? { .id == auth_descriptor_id, .account == account },
                                    "Auth descriptor '%s' not found for account '%s'".format(auth_descriptor_id, account_id)
                                    );

                                    return (account, auth_descriptor);
                                    }

                                    function get_auth_flags(op_name: name, is_strict: boolean) = get_auth_handler(op_name, is_strict).flags;

                                    function get_auth_message_template(op_name: name, op_args: gtv, is_strict: boolean) {
                                    val formatter = get_auth_handler(op_name, is_strict).message_formatter;

                                    val message = if (formatter??) formatter(op_args) else generate_operation_auth_message(chain_context.blockchain_rid, gtx_operation(
                                    name = op_name,
                                    args = list<gtv>.from_gtv(op_args)
                                    ));

                                    return utils.make_auth_message(message);
                                    }

                                    function _validate_evm_signature(
                                    op: gtx_operation,
                                    auth_op: gtx_operation,
                                    is_strict: boolean,
                                    flags: list<text>,
                                    account: accounts.account,
                                    auth_descriptor: accounts.account_auth_descriptor
                                    ) {
                                    val message_template = get_auth_message_template(op.name, op.args.to_gtv(), is_strict);
                                    val validated_args = _validate_evm_arguments(auth_op.args, set(flags), account, auth_descriptor);
                                    val message = create_message_from_template(
                                    validated_args,
                                    message_template,
                                    op.args,
                                    auth_descriptor.ctr
                                    );

                                    if (auth_descriptor.auth_type == accounts.auth_type.S)
                                    _validate_evm_address(message, validated_args.signatures[0], auth_descriptor);
                                    else
                                    _validate_multiple_evm_addresses(message, validated_args.signatures, auth_descriptor);
                                    }

                                    function create_message_from_template(accounts.evm_auth_args, message_template: text, args: list<gtv>, ctr: integer): text {
                                    require(message_template.contains("{nonce}"), "Message template has to include '{nonce}'");
                                    require(message_template.contains("{blockchain_rid}"), "Message template has to include '{blockchain_rid}'");
                                    var message = message_template;

                                    // TODO: check if this is still needed
                                    for (i in range(args.size())) {
                                    message = message.replace("{%d}".format(i), "%s".format(args[i]).replace("\"", ""));
                                    }

                                    return message
                                    .replace("{account_id}", evm_auth_args.account.id.to_hex())
                                    .replace("{auth_descriptor_id}", evm_auth_args.account_auth_descriptor.id.to_hex())
                                    .replace("{nonce}", ctr.to_text().replace("\"", ""))
                                    .replace("{blockchain_rid}", chain_context.blockchain_rid.to_hex());
                                    }

                                    function _validate_evm_arguments(
                                    auth_args: list<gtv>,
                                    required_flags: set<text>,
                                    account: accounts.account,
                                    auth_descriptor: accounts.account_auth_descriptor
                                    ): accounts.evm_auth_args {
                                    require(auth_args.size() == 3, "Incorrect number of arguments to auth operation");

                                    val signatures = list<signature>.from_gtv(auth_args[2]);

                                    val has_all_flags = accounts.has_flags(auth_descriptor, list(required_flags));

                                    require(has_all_flags, "The auth descriptor does not have the required permissions");

                                    return accounts.evm_auth_args(account, auth_descriptor, signatures);
                                    }

                                    function _validate_ft4_signature(
                                    flags: list<text>,
                                    account: accounts.account,
                                    auth_descriptor: accounts.account_auth_descriptor
                                    ) {
                                    val result: utils.validation_result = accounts.check_auth_args(
                                    auth_descriptor.auth_type,
                                    auth_descriptor.args,
                                    accounts.get_signers(auth_descriptor.auth_type, auth_descriptor.args),
                                    flags
                                    );

                                    require(result.valid, result.error!!); // Prints a precise error message.
                                    }

                                    function _recover_evm_address(message: text, signature) {
                                    require(message != "", "Empty messages are not allowed");

                                    val msg_hash = _evm_message_hash(message);
                                    val evm_pubkey = crypto.eth_ecrecover(
                                    signature.r,
                                    signature.s,
                                    signature.v - 27,
                                    msg_hash
                                    );

                                    return crypto.eth_pubkey_to_address(evm_pubkey);
                                    }

                                    function _evm_message_hash(message: text): byte_array =
                                    keccak256(("\u0019Ethereum Signed Message:\n" + message.size().to_text() + message).to_bytes());

                                    function _validate_evm_address(message: text, signature, accounts.account_auth_descriptor) {
                                    val recovered_address = _recover_evm_address(message, signature);
                                    val signer = accounts.auth_descriptor_signer @? {
                                    .account_auth_descriptor == account_auth_descriptor,
                                    .id == recovered_address
                                    };
                                    require(signer, "Invalid signature on message: \n%s".format(message));

                                    return recovered_address;
                                    }

                                    function _validate_multiple_evm_addresses(message: text, signatures: list<signature>, accounts.account_auth_descriptor) {
                                    val recovered_keys = list<byte_array>();
                                    for (i in range(signatures.size())) {
                                    recovered_keys.add(
                                    _validate_evm_address(
                                    message,
                                    signatures[i],
                                    account_auth_descriptor
                                    )
                                    );
                                    }
                                    require(
                                    recovered_keys.size() >= accounts.multi_sig_args.from_bytes(account_auth_descriptor.args).signatures_required,
                                    "Minimum number of valid signatures not reached"
                                    );
                                    return recovered_keys;
                                    }

                                    function extract_account_id(auth_op: gtx_operation): byte_array {
                                    require(is_auth_op(auth_op), "Operation %s is not an auth operation".format(auth_op.name));
                                    require(auth_op.args.size() >= 1, "Invalid auth op, insufficient number of args: %s".format(auth_op.args.size()));
                                    return byte_array.from_gtv(auth_op.args[0]);
                                    }

                                    function is_auth_op(op: gtx_operation) = op.name in [EVM_AUTH_OP, FT_AUTH_OP];

operation evm_auth(
account_id: byte_array,
auth_descriptor_id: byte_array,
signatures: list<auth.signature>
) {}

operation ft_auth(
account_id: byte_array,
auth_descriptor_id: byte_array
) {}

struct _auth_handler_client {
                                    name: text;
                                    flags: list<text>;
                                    dynamic: boolean;
                                    }

                                    query get_auth_flags(op_name: name) = auth.get_auth_handler(op_name, is_strict=false).flags;

                                    query get_auth_message_template(op_name: name, op_args: gtv) = auth.get_auth_message_template(op_name, op_args, is_strict=false);

                                    query get_login_config(name? = null) {
                                    val configs = auth.login_config();
                                    val config_name = name ?: auth.DEFAULT_LOGIN_CONFIG_NAME;

                                    if (config_name == auth.DEFAULT_LOGIN_CONFIG_NAME) {
                                    return if (config_name in configs) configs[config_name] else auth._login_config(flags = []);
                                    }

                                    return require(
                                    configs.get_or_null(config_name),
                                    "Unknown login configuration <%s>".format(config_name)
                                    );
                                    }

                                    query get_auth_handler_for_operation(op_name: name) {
                                    val handler = auth.get_auth_handler(op_name, is_strict=false);
                                    return _auth_handler_client(
                                    name=op_name,
                                    flags=handler.flags,
                                    dynamic=handler.resolver != null
                                    );
                                    }

                                    query get_first_allowed_auth_descriptor_by_signers(
                                    op_name: name,
                                    args: gtv,
                                    account_id: byte_array,
                                    signers: list<byte_array>
                                    ): byte_array? = auth.get_first_allowed_auth_descriptor_by_signers(op_name, args, account_id, signers, is_strict=false);

                                    query get_first_allowed_auth_descriptor(
                                    op_name: name,
                                    args: gtv,
                                    account_id: byte_array,
                                    ad_ids: list<byte_array>
                                    ): byte_array? = auth.get_first_allowed_auth_descriptor(op_name, args, account_id, ad_ids, is_strict=false);

                                    query get_all_auth_handlers() {
                                    val auth_handlers = auth.auth_handler();
                                    return auth_handlers @* {}(
                                    _auth_handler_client(
                                    name=$[0],
                                    flags=$[1].flags,
                                    dynamic=$[1].resolver != null
                                    )
                                    );
                                    }

val DEFAULT_LOGIN_CONFIG_NAME = "default";

struct _login_config {
flags: list<text>;
rules: gtv? = null;
}

@extendable
function login_config(): map<name, _login_config>;

function add_login_config(
name = DEFAULT_LOGIN_CONFIG_NAME,
flags: list<text>,
rules: gtv? = null
) {
return [name: _login_config(flags, rules)];
}

function map_rule(rule: rule_expression): gtv {
return [
rule.operator.name.to_gtv(),
rule.variable.name.to_gtv(),
rule.value.to_gtv()
].to_gtv();
}

function login_simple_rule(rule: rule_expression) = map_rule(rule);

function login_rules(rules_list: list<rule_expression>): gtv {
require(rules_list.size() > 0, "Empty login rules list");

if (rules_list.size() == 1) return map_rule(rules_list[0]);

val rules = ["and".to_gtv()];
for (rule in rules_list) {
rules.add(map_rule(rule));
}
return rules.to_gtv();
}

function ttl(millis: integer): gtv {
return map_rule(
rule_expression(
rule_operator.lt,
rule_variable.relative_block_time,
millis
)
);
}

enum rule_variable {
block_height,
block_time,
op_count,
relative_block_height,
relative_block_time
}

enum rule_operator {
lt,
le,
eq,
ge,
gt
}

struct rule_expression {
operator: rule_operator;
variable: rule_variable;
value: integer;
}

struct rule_parameters {
variable: rule_variable;
value: integer;
}

/*
* Operator functions
*/

function greater_than(rule_parameters) = rule_expression(
rule_parameters.variable,
rule_operator.gt,
rule_parameters.value
);

function greater_or_equal(rule_parameters) = rule_expression(
rule_parameters.variable,
rule_operator.ge,
rule_parameters.value
);

function equals(rule_parameters): rule_expression {
return rule_expression(
rule_parameters.variable,
rule_operator.eq,
rule_parameters.value
);
}

function less_than(rule_parameters) = rule_expression(
rule_parameters.variable,
rule_operator.lt,
rule_parameters.value
);

function less_or_equal(rule_parameters) = rule_expression(
rule_parameters.variable,
rule_operator.le,
rule_parameters.value
);

/*
* Rule variable functions
*/

function block_height(integer) = rule_parameters(
rule_variable.block_height,
integer
);

function block_time(integer) = rule_parameters(
rule_variable.block_time,
integer
);

function op_count(integer) = rule_parameters(
rule_variable.op_count,
integer
);

function relative_block_height(integer) = rule_parameters(
rule_variable.relative_block_height,
integer
);

function relative_block_time(integer) = rule_parameters(
rule_variable.relative_block_time,
integer
);

@mount('ft4')
                                    module;

                                    import ^.accounts;
                                    import ^.utils;
                                    import ^.version;
                                    import .external;

                                    struct auth_data {
                                    flags: list<text>;
                                    message: text;
                                    }

                                    struct _auth_handler {
                                    flags: list<text>;
                                    message_formatter: ((gtv) -> text)? = null;
                                    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null;
                                    }

                                    /*
                                    * The constant that defines app level authentication scope.
                                    * If scope is omitted when defining an auth handler, then
                                    * it has 'app' scope, i.e. it is used to authenticate
                                    * operations that do not have own auth handlers or if
                                    * there is no mount point auth handler for the operation.
                                    */
                                    val APP_SCOPE = "app";

                                    /*
                                    * Extendable function used to define auth handlers.
                                    * When called it returns a list of all auth handlers defined
                                    * in the dapp.
                                    */
                                    @extendable
                                    function auth_handler(): map<name, _auth_handler>;

                                    /*
                                    * Finds auth handler for provided operation name.
                                    */
                                    function get_auth_handler(op_name: name, is_strict: boolean) {
                                    require_valid_scope_name(op_name);
                                    val auth_handlers = auth_handler();
                                    if (op_name in auth_handlers) return auth_handlers[op_name];
                                    val override_name = "__override__" + op_name;
                                    if (override_name in auth_handlers) return auth_handlers[override_name];

                                    require(not is_strict, "Strict mode is used and no auth handler matches exactly <%s>".format(op_name));

                                    val handler = get_mount_scope_auth_handler(auth_handlers, op_name);
                                    if (handler??) return handler;

                                    require(
                                    auth_handlers.get_or_null(APP_SCOPE),
                                    "Cannot find auth handler for operation <%s>".format(op_name)
                                    );
                                    return auth_handlers[APP_SCOPE];
                                    }

                                    function add_auth_handler(
                                    scope: text = APP_SCOPE,
                                    flags: list<text>,
                                    message: ((gtv) -> text)? = null,
                                    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null
                                    ) = [valid_scope_name(scope): _auth_handler(flags, message, resolver)];

                                    function add_overridable_auth_handler(
                                    scope: text = APP_SCOPE,
                                    flags: list<text>,
                                    message: ((gtv) -> text)? = null,
                                    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null
                                    ) = ["__override__" + valid_scope_name(scope): _auth_handler(flags, message, resolver)];

                                    function valid_scope_name(scope: text) {
                                    val scope_name = scope.trim();
                                    require_valid_scope_name(scope_name);
                                    return scope_name;
                                    }

                                    function args() = op_context.get_all_operations()[op_context.op_index].args.to_gtv();

                                    struct signature {
                                    r: byte_array;
                                    s: byte_array;
                                    v: integer;
                                    }

                                    function get_mount_scope_auth_handler(auth_handlers: map<name, _auth_handler>, op_name: name) {
                                    val op_name_components = op_name.split(".");
                                    if (op_name_components.size() < 2) return null;

                                    for (count in range(op_name_components.size()-1, 0, -1)) {
                                    val mount_point = join_text_list(op_name_components, count);
                                    if (mount_point in auth_handlers) return auth_handlers[mount_point];
                                    }

                                    return null;
                                    }

                                    /*
                                    * Creates message from operation name and arguments.
                                    * It is used when `evm_auth` is used to authenticate a user,
                                    * but auth message is not specified in the auth handler of the operation.
                                    */
                                    function generate_operation_auth_message(blockchain_rid: byte_array, op: gtx_operation) {
                                    var message = "Please sign the message to call\noperation:\n- %s".format(op.name);

                                    if (op.args.size() > 0) {
                                    message = message + "\n\n";
                                    var arguments = "with arguments:\n";
                                    for (arg in op.args) {
                                    arguments = arguments + "- %s\n".format(arg).replace("\"", "");
                                    }
                                    message = message + arguments.sub(0, arguments.size() - 1);
                                    }

                                    return message;
                                    }

                                    function join_text_list(components: list<text>, count: integer) {
                                    require(count < components.size() and count > 0, "Error building mount path");
                                    var result = components[0];
                                    for (i in range(1, count)) {
                                    result = result + "." + components[i];
                                    }
                                    return result;
                                    }

                                    function require_valid_scope_name(name) =
                                    require(
                                    name.matches("^\\w+(\\.\\w+)*$"),
                                    "Invalid scope name <%s>".format(name)
                                    );

module;

                                    namespace ft4 {
                                    import acc: ^.accounts;
                                    import ^.accounts;
                                    import ^.assets;
                                    import ^.auth;
                                    import ^.admin;
                                    import acc_ext: ^.accounts.external;
                                    import accounts_ext: ^.accounts.external;
                                    import assets_ext: ^.assets.external;
                                    import ^.version;
                                    }

struct module_args {
                                    query_max_page_size: integer = 100;
                                    }

                                    function get_module_args() {
                                    return chain_context.args;
                                    }

import ^.{ get_module_args };

                                    struct page_cursor {
                                    before_rowid: rowid? = null;
                                    }

                                    struct pagination_result {
                                    data: gtv;
                                    rowid: rowid;
                                    }

                                    function encode_cursor(page_cursor) = page_cursor.to_bytes().to_base64();

                                    function decode_cursor(cursor: text) = page_cursor.from_bytes(byte_array.from_base64(cursor));

                                    struct paged_result {
                                    next_cursor: text?;
                                    data: list<gtv>;
                                    }

                                    function null_page() = paged_result(
                                    next_cursor = null,
                                    data = list<gtv>()
                                    );

                                    function fetch_data_size(page_size: integer? = get_module_args().query_max_page_size) =
                                    min(get_module_args().query_max_page_size, page_size ?: get_module_args().query_max_page_size) + 1;

                                    function before_rowid(page_cursor: text?) {
                                    var before_rowid: rowid? = null;
                                    if (page_cursor??) {
                                    val cursor = decode_cursor(page_cursor);
                                    before_rowid = cursor.before_rowid;
                                    }
                                    return before_rowid;
                                    }


                                    function make_page(pagination_results: list<pagination_result>, page_size: integer?): paged_result {
                                    if (page_size != null) {
                                    require(page_size > 0, "Must return at least one item");
                                    }
                                    if (empty(pagination_results)) {
                                    return null_page();
                                    }
                                    // adding +1 should help with next page null situation when current page size
                                    // is equal to max page size
                                    if(pagination_results.size() < fetch_data_size(page_size)) {
                                    return paged_result(
                                    next_cursor = null,
                                    data = pagination_results  @* {} .data
                                    );
                                    }
                                    val paginated_result = pagination_results.sub(0, pagination_results.size()-1);
                                    val next_id = pagination_results[pagination_results.size()-2].rowid;
                                    val next_cursor = page_cursor(
                                    next_id
                                    );
                                    return paged_result(
                                    next_cursor = encode_cursor(next_cursor),
                                    data = paginated_result  @* {} .data
                                    );
                                    }

/*
                                    * For complex validation we might not want to use simple "require()"
                                    * but an error message that is returned.
                                    */
                                    struct validation_result {
                                    valid: boolean;
                                    error: text? = null;
                                    }

                                    val VALID = validation_result(true, null);

                                    function invalid(error: text) = validation_result(false, error);

                                    function make_auth_message(message: text) {
                                    return "Blockchain:\n{blockchain_rid}\n\n" + message + "\n\nNonce: {nonce}";
                                    }

